import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
import assert from 'node:assert/strict';
const exec = promisify(execFile);
const query = async sql => (await exec('psql', ['-X','-v','ON_ERROR_STOP=1','-At','-c',sql])).stdout.trim();
await query('create role anon; create role authenticated; create role service_role bypassrls;');
for (let i=0;i<2;i++) await exec('psql',['-X','-v','ON_ERROR_STOP=1','-f','supabase/migrations/202610220040_jira_support.sql']);
for (const role of ['anon','authenticated']) {
  await assert.rejects(query('set role '+role+'; select * from public.support_tickets;'));
  await assert.rejects(query('set role '+role+"; select public.claim_support_attempt(repeat('a',64),'support');"));
}
const attempts=await Promise.all(Array.from({length:8},()=>query("select public.claim_support_attempt(repeat('a',64),'support');")));
assert.equal(attempts.filter(x=>x==='t').length,5);
await query("update public.support_rate_limits set window_start=now()-interval '11 minutes';");
assert.equal(await query("select public.claim_support_attempt(repeat('a',64),'support');"),'t');
const id=await query("insert into public.support_tickets(input) values('{}') returning id;");
const uuid=id.split('\n')[0];
const claims=await Promise.all(Array.from({length:8},()=>query("select row_to_json(t) from public.claim_support_ticket('"+uuid+"')t;")));
const claimed=claims.filter(Boolean); assert.equal(claimed.length,1);
const first=JSON.parse(claimed[0]);
await query("update public.support_tickets set status='sending',locked_until=now()-interval '1 second' where id='"+uuid+"';");
const next=JSON.parse(await query("select row_to_json(t) from public.claim_support_ticket('"+uuid+"')t;"));
assert.equal(next.status,'needs_review'); assert.notEqual(next.lease_token,first.lease_token);
await assert.rejects(query("insert into public.support_tickets(input,telemetry_id) values('{}','"+uuid+"'),('{}','"+uuid+"');"));
for(let i=0;i<60;i++) await query("select public.record_support_telemetry(jsonb_build_object('id',gen_random_uuid(),'message','failure "+i+"'),'hash-"+i+"');");
assert.equal(await query('select count(*) from public.support_telemetry;'),'50');
const prior=await query("select public.record_support_telemetry(jsonb_build_object('id',gen_random_uuid(),'message','same'),'duplicate');");
const repeated=await query("select public.record_support_telemetry(jsonb_build_object('id',gen_random_uuid(),'message','same'),'duplicate');");
assert.equal(prior,repeated);
assert.equal(await query('select count(*) from public.support_telemetry;'),'50');
